/** Real compound hosts, all palettes and two GUI scales; no live server mutations. */
@EventBusSubscriber(modid="anthub",value=Dist.CLIENT)
public final class DialogUiHarness {
 private static final int HOSTS=28;private static int step=-1;private static long at;private static CommunityScreen parent;
 private static int total(){return UiPalette.names().size()*HOSTS*2;}
 @SubscribeEvent public static void tick(ScreenEvent.Render.Post event){String output=System.getenv("ANTHUB_DIALOG_UI");if(output==null||step>=total())return;var mc=Minecraft.getInstance();if(step<0){if(!(mc.screen instanceof TitleScreen))return;int selected=UiPalette.selected();for(int theme=0;theme<UiPalette.names().size();theme++){UiPalette.preview(theme);NativeUiHarness.verifyContrast();}UiPalette.preview(selected);System.out.println("ANTHUB_DIALOG_THEME_ROLES_OK");CommunityUiHarness.open("normal");verifyContracts();var original=ServerMenuClient.previewTransport;ServerMenuClient.previewTransport=q->{String op=Json.opt(q,"op",""),action=Json.opt(q,"action","");if(op.startsWith("work")||op.startsWith("tools")||action.equals("adminDashboard"))NextUiHarness.request(q);else original.accept(q);};step=0;at=System.currentTimeMillis()+900;return;}if(System.currentTimeMillis()<at)return;at=System.currentTimeMillis()+280;
 try{if(step>0){bounds();var dir=new java.io.File(output);dir.mkdirs();net.minecraft.client.Screenshot.grab(dir,String.format("dialog-%03d.png",step),mc.getMainRenderTarget(),m->{});}int host=step%HOSTS,group=step/HOSTS;UiPalette.preview(group%UiPalette.names().size());if(host==0){mc.options.guiScale().set(2+group/UiPalette.names().size());mc.resizeDisplay();parent=new CommunityScreen(null,"board","");mc.setScreen(parent);}
 var preset=new JsonObject();preset.addProperty("title","Пример записи");preset.addProperty("description","Проверка общей формы и читаемости. ".repeat(8));var fields=List.of(new CommunityScreen.Field("title","Название",100),new CommunityScreen.Field("description","Описание",1500));
 switch(host){case 0->mc.setScreen(new NotificationPopup(parent));case 1->mc.setScreen(new GlobalSearchScreen(parent));case 2->mc.setScreen(new CommunityForm(parent,"Редактировать запись",fields,preset,q->{}));case 3->mc.setScreen(new TaskEditScreen(parent,"Редактировать этап",fields,preset,q->{}));case 4->mc.setScreen(new UiConfirmDialog(yes->mc.setScreen(parent),Component.literal("Подтверждение"),Component.literal("Проверка общего диалога подтверждения. ".repeat(12))));case 5->mc.setScreen(new TextScreen(parent,Component.literal("Информация"),"Строка с описанием\n".repeat(45)));case 6->mc.setScreen(new AccessibilityScreen(parent));case 7->mc.setScreen(new CommunityPreferences(parent,new JsonObject()));case 8->mc.setScreen(new QuickSkinsScreen(parent));case 9->mc.setScreen(new LocationEditor(parent,null,true,q->{}));case 10->mc.setScreen(new MemberPickerScreen(parent,new JsonArray(),q->{}));case 11->mc.setScreen(new ItemPickerScreen(parent,q->{}));case 12->mc.setScreen(new TaskResourcesScreen(parent,new JsonArray(),q->{}));case 13->mc.setScreen(new DateTimeScreen(parent,"",q->{}));case 14->mc.setScreen(new ReportScreen(parent));case 15->mc.setScreen(new HomeWidgetsScreen(parent));case 16->mc.setScreen(new PersonalProfileScreen(parent));case 17->mc.setScreen(new FollowingScreen(parent));case 18->mc.setScreen(new PrivacyScreen(parent));case 19->mc.setScreen(new MapSharingScreen(parent));case 20->mc.setScreen(new PlacesScreen(parent));case 21->mc.setScreen(new AdminDashboardScreen(parent,true));case 22->mc.setScreen(new TaskMemberPicker(parent,"",q->{}));case 24,25->{var empty=new JsonObject();empty.addProperty("title","");empty.addProperty("description","");if(host==24)mc.setScreen(new CommunityForm(parent,"Новая запись",fields,empty,q->{}));else mc.setScreen(new TaskEditScreen(parent,"Новый этап",fields,empty,q->{}));for(var c:mc.screen.children())if(c instanceof Button b&&UiActions.style(b).tone()==UiActions.Tone.PRIMARY){b.onPress();break;}}case 26,27->{var resources=new JsonArray();for(int n=0;n<30;n++){var row=new JsonObject();row.addProperty("item","minecraft:stone");row.addProperty("amount",64);resources.add(row);}var editor=new TaskResourcesScreen(parent,resources,q->{});mc.setScreen(editor);editor.mouseScrolled(editor.scrollLayout().viewport().x()+4,editor.scrollLayout().viewport().y()+4,0,-4);UiGeometryHarness.verify(editor);if(host==27){var picker=new ItemPickerScreen(editor,q->{});mc.setScreen(picker);var owner=picker.scrollLayout().viewport();picker.mouseScrolled(owner.x()+4,owner.y()+4,0,-12);UiGeometryHarness.verify(picker);}}case 23->mc.setScreen(new ChoicePopup(parent,"Действия",List.of("Первое действие","Второе действие","Третье действие"),q->{}));}
 step++;if(step==total()){bounds();System.out.println("ANTHUB_DIALOG_OK: "+total()+" states, "+UiPalette.names().size()+" themes");mc.stop();}}
 catch(Throwable failure){System.out.println("ANTHUB_DIALOG_FAILED step="+step);step=total();failure.printStackTrace();mc.stop();}}
 static void verifyContracts(){verifyFormGrid();verifyInteractions();UiFlowHarness.verify();var mc=Minecraft.getInstance();var previous=mc.screen;var answers=new ArrayList<Boolean>();var cancelled=new UiConfirmDialog(yes->{answers.add(yes);mc.setScreen(previous);},Component.literal("Проверка отмены"),Component.literal("Тест"));mc.setScreen(cancelled);cancelled.onClose();cancelled.onClose();if(!answers.equals(List.of(false))||mc.screen!=previous)throw new IllegalStateException("Confirmation cancellation dispatched more than once");answers.clear();var accepted=new UiConfirmDialog(yes->{answers.add(yes);mc.setScreen(previous);},Component.literal("Проверка подтверждения"),Component.literal("Тест"));mc.setScreen(accepted);((Button)accepted.children().getFirst()).onPress();accepted.onClose();if(!answers.equals(List.of(true))||mc.screen!=previous)throw new IllegalStateException("Confirmation acceptance dispatched more than once");var vanilla=new TitleScreen();var button=Button.builder(Component.literal("Vanilla"),b->{}).bounds(0,0,80,20).build();UiTheme.rendering(vanilla,()->{if(UiTheme.stylesButtons(accepted,button))throw new IllegalStateException("Modal styles leaked into vanilla parent");});System.out.println("ANTHUB_DIALOG_CONTRACTS_OK: cancel, single answer, vanilla parent isolation");}
 private static void verifyInteractions(){
  var mc=Minecraft.getInstance();var previous=mc.screen;var preset=new JsonObject();preset.addProperty("title","До изменения");
  var editor=new TaskEditScreen(previous,"Проверка навигации",List.of(new CommunityScreen.Field("title","Название",100)),preset,q->{});
  mc.setScreen(editor);((EditBox)editor.children().getFirst()).setValue("Изменено");
  UiNavigation.handle(editor,256);if(!(mc.screen instanceof UiConfirmDialog))throw new IllegalStateException("Escape bypassed unsaved changes");
  UiNavigation.handle(mc.screen,256);if(mc.screen!=editor)throw new IllegalStateException("Cancel did not restore editor");
  editor.setFocused(null);UiNavigation.handle(editor,259);if(!(mc.screen instanceof UiConfirmDialog))throw new IllegalStateException("Backspace bypassed unsaved changes");
  UiNavigation.handle(mc.screen,259);if(mc.screen!=editor)throw new IllegalStateException("Backspace cancellation did not restore editor");mc.setScreen(previous);
  var scroll=new ScrollScreen(Component.literal("Scroll test")){
   @Override protected void init(){scrollArea(100,new dev.abros.anthub.core.NativeLayout.Box(10,20,96,100),10);}
   @Override protected void rowsChanged(){}
  };
  mc.setScreen(scroll);scroll.mouseScrolled(100,50,0,-10);int before=scroll.firstRow;
  int thumbY=20+(int)(88*before/90.0);scroll.mouseClicked(102,thumbY+2,0);
  if(scroll.firstRow!=before)throw new IllegalStateException("Scrollbar jumped on grab");
  scroll.mouseDragged(102,thumbY+12,0,0,10);if(scroll.firstRow<=before)throw new IllegalStateException("Scrollbar drag did not move");
  scroll.mouseReleased(102,thumbY+12,0);mc.setScreen(previous);
  var enabled=new boolean[]{true};var lifecycle=new ScrollScreen(Component.literal("Lifecycle")){
   protected void init(){if(enabled[0])scrollArea(100,new dev.abros.anthub.core.NativeLayout.Box(10,20,96,100),10);}
  };
  mc.setScreen(lifecycle);if(lifecycle.scrollLayout()==null)throw new IllegalStateException("List geometry missing");
  enabled[0]=false;lifecycle.rebuildWidgets();if(lifecycle.scrollLayout()!=null)throw new IllegalStateException("Previous tab scrollbar survived rebuild");
  enabled[0]=true;lifecycle.rebuildWidgets();UiGeometryHarness.verify(lifecycle);mc.setScreen(previous);
  System.out.println("ANTHUB_INTERACTIONS_OK: protected navigation and stable scrollbar drag");
 }
 private static void verifyFormGrid(){var fields=new ArrayList<UiFormGrid.Field>();fields.add(new UiFormGrid.Field(new CommunityScreen.Field("title","Название",100),true,false,""));for(String key:List.of("x","y","z"))fields.add(new UiFormGrid.Field(new CommunityScreen.Field(key,key,10),false,false,"coordinates"));fields.add(new UiFormGrid.Field(new CommunityScreen.Field("description","Описание",1500),true,true,""));var mixed=UiFormGrid.layout(List.of(new UiFormGrid.Field(new CommunityScreen.Field("a","A",100),false,false,""),new UiFormGrid.Field(new CommunityScreen.Field("b","B",100),false,true,"")),400);if(mixed.stream().anyMatch(c->c.units()!=3))throw new IllegalStateException("Mixed form row clipped multiline input");for(int width=120;width<=720;width++){var cells=UiFormGrid.layout(fields,width);if(cells.size()!=fields.size())throw new IllegalStateException("Form grid lost a field");int containerWidth=width;var boxes=cells.stream().map(c->c.bounds(10,20,containerWidth,0)).toList();for(var box:boxes)if(box.x()<10||box.right()>10+width||box.width()<=0)throw new IllegalStateException("Form grid left its container");for(int a=0;a<boxes.size();a++)for(int b=a+1;b<boxes.size();b++){var x=boxes.get(a);var y=boxes.get(b);if(x.x()<y.right()&&y.x()<x.right()&&x.y()<y.bottom()&&y.y()<x.bottom())throw new IllegalStateException("Form grid overlaps fields");}}System.out.println("ANTHUB_FORM_GRID_OK: widths 120–720, related coordinates and multiline fields");}
 private static void bounds(){var s=Minecraft.getInstance().screen;UiGeometryHarness.verify(s);var widgets=s.children().stream().filter(c->c instanceof AbstractWidget).map(c->(AbstractWidget)c).filter(w->w.visible).toList();for(var w:widgets)if(w.getX()<0||w.getY()<0||w.getX()+w.getWidth()>s.width||w.getY()+w.getHeight()>s.height||w.getHeight()<=0||w.getWidth()<=0)throw new IllegalStateException(s.getClass().getSimpleName()+" invalid bounds: "+w.getMessage().getString());for(int i=0;i<widgets.size();i++)for(int n=i+1;n<widgets.size();n++){var a=widgets.get(i);var b=widgets.get(n);if(a.getX()<b.getX()+b.getWidth()&&b.getX()<a.getX()+a.getWidth()&&a.getY()<b.getY()+b.getHeight()&&b.getY()<a.getY()+a.getHeight())throw new IllegalStateException(s.getClass().getSimpleName()+" overlaps: "+a.getMessage().getString()+" / "+b.getMessage().getString());}}
}
